// Node: Build Sync Window   ([SPL] HubSpot -> Simpro Quotes Sync)
// Settings + time window for this sync. Single source of truth: edit values HERE only.
// The watermark lives in THIS workflow's own static data, so the five HubSpot -> Simpro syncs never share a window.
const CONFIG = {
  recordType: 'quote', // company | contact | site | quote | job
  label: 'Quotes',
  // --- TEST MODE: while true, only TEST records are sent to Simpro. Set to false to send everything. ---
  testOnly: true,
  // A record is a test record when its name starts with namePrefix OR its own email domain is in emailDomains (case-insensitive).
  testRecords: { namePrefix: 'HSTEST-', emailDomains: ['aniccadigital.io', 'spl.com.au'], nameFields: ['dealname'], emailField: null },
  // --- HubSpot ---
  hubspotApiBase: 'https://api.hubapi.com',
  objectPath: 'crm/objects/2026-09/deals',
  assocObject: 'deals', // object type name used by the associations API
  idProperty: 'simpro_quote_id', // HubSpot property that holds the Simpro ID
  modifiedProperty: 'hs_lastmodifieddate', // what 'changed' means in HubSpot
  pipelineId: 'default', // deals: only this pipeline
  onlyAlreadyInSimpro: false, // true = only records that already have a Simpro ID (never creates new ones in Simpro), as today
  properties: ['simpro_quote_id', 'dealname', 'simpro_description', 'description', 'hubspot_owner_id', 'project_manager', 'due_date', 'orderno', 'validity', 'project_tags', 'quote_type', 'tender_number', 'tender_status', 'vertical'],
  // --- Simpro ---
  simproBaseUrl: 'https://spl.simprosuite.com/api/v1.0',
  simproCompanyId: 4, // quotes and jobs live under Simpro company 4 (confirmed with SPL)
  decisionMakerTypeId: 10, // HubSpot association label Decision Maker: the contact with it is the Simpro CustomerContact
  costCenterTotalField: 'ExTax', // line item price is GST-exclusive. NOTE: confirm on the first run that Simpro accepts Total.ExTax when writing a cost center
  customFields: { tenderNumber: 35, tenderStatus: 36, vertical: 49 }, // Simpro custom field IDs
  // --- Window (use windowStartOverride for a one-off backfill, e.g. '2020-01-01T00:00:00Z', then clear it) ---
  overlapMinutes: 5, // re-read this far back from the last window end (late edits). Writes only happen when something differs.
  initialLookbackMinutes: 35, // used when there is no saved watermark (first run, or any manual test run)
  windowStartOverride: '',
};

const state = $getWorkflowStaticData('global'); // only persists on production (trigger) runs, not manual test runs
const now = new Date();
let from;
let fromSource;
if (CONFIG.windowStartOverride) {
  from = new Date(CONFIG.windowStartOverride);
  if (isNaN(from.getTime())) throw new Error('windowStartOverride is not a valid ISO date-time: ' + CONFIG.windowStartOverride);
  fromSource = 'override';
} else if (state.lastWindowEnd) {
  from = new Date(new Date(state.lastWindowEnd).getTime() - CONFIG.overlapMinutes * 60000);
  fromSource = 'watermark';
} else {
  from = new Date(now.getTime() - CONFIG.initialLookbackMinutes * 60000);
  fromSource = 'initial lookback';
}
if (from.getTime() >= now.getTime()) {
  throw new Error('Sync window starts in the future (' + from.toISOString() + '). Check windowStartOverride and the saved watermark.');
}

// The HubSpot search: records changed since the window start (+ the pipeline for deals, + "already in Simpro" if set).
const filters = [{ propertyName: CONFIG.modifiedProperty, operator: 'GTE', value: String(from.getTime()) }];
if (CONFIG.pipelineId) filters.push({ propertyName: 'pipeline', operator: 'EQ', value: CONFIG.pipelineId });
if (CONFIG.onlyAlreadyInSimpro) filters.push({ propertyName: CONFIG.idProperty, operator: 'HAS_PROPERTY' });

return [{ json: {
  ...CONFIG,
  searchUrl: CONFIG.hubspotApiBase + '/' + CONFIG.objectPath + '/search',
  searchBody: { filterGroups: [{ filters }], properties: CONFIG.properties, sorts: ['hs_object_id'], limit: 200 },
  windowFrom: from.toISOString(),
  windowTo: now.toISOString(),
  fromSource,
} }];

// Node: Prepare Records   (all five HubSpot -> Simpro sync workflows)
// Collects every page of the HubSpot search into ONE list of changed records and applies the test-record rule
// (while testOnly is on). One state item out; later nodes read it with $('Prepare Records').first().
const cfg = $('Build Sync Window').first().json;
const pages = $('Find Changed Records').all().map(i => i.json);

const seen = new Set();
const found = [];
let rows = 0;
let reportedTotal = null;
for (const page of pages) {
  if (!Array.isArray(page.results)) {
    throw new Error('Find Changed Records: expected a results array from HubSpot, got ' + JSON.stringify(page).slice(0, 300));
  }
  if (reportedTotal === null && page.total !== undefined) reportedTotal = Number(page.total);
  for (const row of page.results) {
    if (row === null || typeof row !== 'object' || !row.id) throw new Error('Find Changed Records: a returned record has no id.');
    rows++;
    if (seen.has(String(row.id))) continue;
    seen.add(String(row.id));
    found.push(row);
  }
}
// The page cap stops silently - fail loudly instead of syncing a partial window.
if (reportedTotal !== null && rows < reportedTotal) {
  throw new Error('Find Changed Records: read ' + rows + ' of ' + reportedTotal + ' changed ' + cfg.label
    + ' (HubSpot search limit reached). Shorten the window (windowStartOverride in Build Sync Window) and run again.');
}

// Test-record rule, same as the Real Time workflow: name starts with the prefix OR the record's own email domain is a test domain.
const rule = cfg.testRecords;
const prefix = String(rule.namePrefix).toLowerCase();
const domains = rule.emailDomains.map(d => String(d).trim().toLowerCase());
const isTest = (p) => {
  const name = rule.nameFields.map(f => p[f]).filter(Boolean).join(' ').trim().toLowerCase();
  if (name.startsWith(prefix)) return true;
  const email = String(rule.emailField ? (p[rule.emailField] ?? '') : '').trim().toLowerCase();
  const domain = email.includes('@') ? email.split('@').pop() : '';
  return domain !== '' && domains.includes(domain);
};

const records = [];
let skippedNonTest = 0;
for (const row of found) {
  const p = row.properties ?? {};
  if (cfg.testOnly && !isTest(p)) { skippedNonTest++; continue; }
  const sid = p[cfg.idProperty];
  records.push({ hsId: String(row.id), simproId: (sid === undefined || sid === null || sid === '') ? null : String(sid), props: p });
}
return [{ json: { hasRecords: records.length > 0, records, counts: { changedInHubSpot: found.length, skippedNonTest } } }];

// Node: Build Association Reads   (contacts, sites, quotes and jobs)
// Which related HubSpot records does each changed record have? One batch read per association type (100 records per call).
// Deals also read their line items. Always at least one request (this node only runs when there are records).
const cfg = $('Build Sync Window').first().json;
const { records } = $('Prepare Records').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const TO = {
  contact: ['companies'],
  site: ['companies', 'contacts'],
  quote: ['companies', 'contacts', '0-420', 'line_items'],
  job: ['companies', 'contacts', '0-420', 'line_items'],
};
const ids = records.map(r => r.hsId);
const requests = [];
for (const to of TO[cfg.recordType] ?? []) {
  chunk(ids, 100).forEach((part, n) => requests.push({
    url: cfg.hubspotApiBase + '/crm/v4/associations/' + cfg.assocObject + '/' + to + '/batch/read',
    body: { inputs: part.map(id => ({ id })) },
    meta: { to, batch: n + 1 },
  }));
}
return requests.map(r => ({ json: r }));

// Node: Build Related Reads   (contacts, sites, quotes and jobs)
// Reads the Simpro ID of every related company / contact / site (and the line items of deals) in batches of 100.
// No related records at all = a single { skip: true } item.
const cfg = $('Build Sync Window').first().json;
const reqs = $('Build Association Reads').all(); // the requests, in the order they were sent
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const need = { companies: new Set(), contacts: new Set(), '0-420': new Set(), line_items: new Set() };
$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = reqs[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return; // none of these records has links of this type
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('HubSpot association read (' + meta.to + ') failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  for (const row of ((r.body && r.body.results) || [])) for (const t of (row.to ?? [])) need[meta.to].add(String(t.toObjectId));
});

const OBJECTS = {
  companies: { path: 'crm/objects/2026-09/companies', properties: ['simpro_customer_id'] },
  contacts: { path: 'crm/objects/2026-09/contacts', properties: ['simpro_contact_id'] },
  '0-420': { path: 'crm/objects/2026-09/0-420', properties: ['simpro_site_id'] },
  line_items: { path: 'crm/objects/2026-09/line_items', properties: ['price', 'simpro_id', 'cost_centre', 'name', 'simpro_section_id'] },
};
const out = [];
for (const [type, set] of Object.entries(need)) {
  chunk([...set], 100).forEach((part, n) => out.push({
    url: cfg.hubspotApiBase + '/' + OBJECTS[type].path + '/batch/read',
    body: { properties: OBJECTS[type].properties, inputs: part.map(id => ({ id })) },
    meta: { type, batch: n + 1 },
  }));
}
if (out.length === 0) return [{ json: { skip: true } }];
return out.map(r => ({ json: r }));

// Node: Resolve Plan   (all five HubSpot -> Simpro sync workflows)
// Turns each changed HubSpot record into a plan for Simpro: where to create/update it, the body to send, and the
// Simpro IDs of the records it links to (read from HubSpot in the previous steps). A record that cannot be sent
// yet (for example its company is not in Simpro) is listed under `skipped`, never created half-linked.
// One state item out; later nodes read it with $('Resolve Plan').first().
const cfg = $('Build Sync Window').first().json;
const { records } = $('Prepare Records').first().json;
const base = cfg.simproBaseUrl;
const blank = (v) => v === null || v === undefined || v === '' || v === 'null';
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;

// --- what each record is linked to in HubSpot: assoc[to][hubspotId] = [{ id, types:Set(typeId) }]
const assoc = { companies: {}, contacts: {}, '0-420': {}, line_items: {} };
const assocReqs = safeAll('Build Association Reads');
safeAll('Read Associations').forEach((item, k) => {
  const meta = assocReqs[idxOf(item, k)].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return;
  for (const row of ((r.body && r.body.results) || [])) {
    assoc[meta.to][String(row.from.id)] = (row.to ?? []).map(t => ({ id: String(t.toObjectId), types: new Set((t.associationTypes ?? []).map(a => Number(a.typeId))) }));
  }
});

// --- the Simpro ID of each related record, and the line item properties
const simproOf = { companies: {}, contacts: {}, '0-420': {} };
const lineItem = {};
const ID_PROP = { companies: 'simpro_customer_id', contacts: 'simpro_contact_id', '0-420': 'simpro_site_id' };
const relReqs = safeAll('Build Related Reads');
safeAll('Read Related Objects').forEach((item, k) => {
  const meta = relReqs[idxOf(item, k)].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return;
  for (const x of ((r.body && r.body.results) || [])) {
    if (meta.type === 'line_items') lineItem[String(x.id)] = x.properties ?? {};
    else if (!blank(x.properties && x.properties[ID_PROP[meta.type]])) simproOf[meta.type][String(x.id)] = String(x.properties[ID_PROP[meta.type]]);
  }
});
// related records of one type that already have a Simpro ID, preferred association type first
const related = (hsId, to, preferType) => {
  const list = (assoc[to][hsId] ?? []).filter(t => simproOf[to][t.id] !== undefined);
  const preferred = preferType ? list.filter(t => t.types.has(preferType)) : [];
  return [...preferred, ...list.filter(t => !preferred.includes(t))].map(t => simproOf[to][t.id]);
};
const notInSimpro = (hsId, to) => (assoc[to][hsId] ?? []).filter(t => simproOf[to][t.id] === undefined).length;

// --- SPL Users data table (HubSpot_ID -> Simpro_ID) for deal owners
const users = {};
for (const row of safeAll('Load SPL Users')) {
  const j = row.json ?? {};
  if (!blank(j.HubSpot_ID) && !blank(j.Simpro_ID)) users[String(j.HubSpot_ID)] = Number(j.Simpro_ID);
}
const asDate = (v) => /^\d+$/.test(String(v)) ? DateTime.fromMillis(Number(v), { zone: 'utc' }) : DateTime.fromISO(String(v), { zone: 'utc' });
const keep = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => !blank(v)));

const plan = [];
const skipped = [];
for (const rec of records) {
  const p = rec.props;
  const out = { hsId: rec.hsId, simproId: rec.simproId, name: '', createUrl: null, updateUrl: null, body: {}, createExtra: {}, links: null, customFields: [], lineItems: [], warnings: [] };
  const skip = (reason) => skipped.push({ hsId: rec.hsId, reason });
  const urlsFor = (collection) => { out.createUrl = collection + '/'; out.updateUrl = rec.simproId ? collection + '/' + rec.simproId : null; };

  if (cfg.recordType === 'company') {
    out.name = p.name ?? '';
    urlsFor(base + '/companies/0/customers/companies');
    out.body = {
      CompanyName: p.name,
      Address: { Address: p.address || '', City: p.city || '', State: p.state || '', PostalCode: p.zip || '', Country: p.country || '' },
      BillingAddress: { Address: p.billing_address || '', City: p.billing_city || '', State: p.billing_state || '', PostalCode: p.billing_zip || p.billing_postalcode || '', Country: p.billing_country || '' }, // billing_zip is what the Simpro -> HubSpot sync writes
      Phone: p.phone || '', Website: p.website || '', EIN: p.abn || '',
    };
  } else if (cfg.recordType === 'contact') {
    out.name = [p.firstname, p.lastname].filter(Boolean).join(' ');
    const customer = related(rec.hsId, 'companies', 1)[0]; // the primary company first
    if (!customer) { skip('its company is not in Simpro yet (no Simpro customer ID)'); continue; }
    urlsFor(base + '/companies/0/customers/' + customer + '/contacts');
    out.body = { GivenName: p.firstname || '', FamilyName: p.lastname || '', Email: p.email || '', WorkPhone: p.phone || '', Title: p.salutation || '', Department: p.department || '', Position: p.jobtitle || '' };
  } else if (cfg.recordType === 'site') {
    out.name = p.hs_name ?? '';
    urlsFor(base + '/companies/0/sites');
    const address = keep({ Address: p.hs_address_1, City: p.hs_city, State: p.hs_state_province, PostalCode: p.hs_zip, Country: p.country });
    const billing = keep({ Address: p.billing_address, City: p.billing_city, State: p.billing_state, PostalCode: p.billing_postal_code });
    out.body = { ...keep({ Name: p.hs_name }), ...(blank(p.zone) ? {} : { Zone: Number(p.zone) }), ...(Object.keys(address).length ? { Address: address } : {}), ...(Object.keys(billing).length ? { BillingAddress: billing } : {}) };
    out.links = { customers: related(rec.hsId, 'companies').map(Number), primaryContact: (related(rec.hsId, 'contacts')[0] ?? null) };
    const missing = notInSimpro(rec.hsId, 'companies');
    if (missing) out.warnings.push(missing + ' linked company(ies) not in Simpro yet - not linked');
  } else { // quote or job
    const isQuote = cfg.recordType === 'quote';
    out.name = p.dealname ?? '';
    const customer = related(rec.hsId, 'companies')[0];
    const site = related(rec.hsId, '0-420')[0];
    if (!customer || !site) { skip('its ' + (!customer ? 'company' : 'site') + ' is not in Simpro yet (no Simpro ID)'); continue; }
    const contact = related(rec.hsId, 'contacts', cfg.decisionMakerTypeId)[0]; // the Decision Maker first, else the first contact
    urlsFor(base + '/companies/' + cfg.simproCompanyId + (isQuote ? '/quotes' : '/jobs'));
    out.body = {
      Customer: Number(customer),
      ...(contact ? { CustomerContact: Number(contact) } : {}),
      Site: Number(site),
      Name: p.dealname ?? '',
      Description: p.simpro_description ?? '',
      Notes: p.description ?? '',
      ...(!isQuote && users[String(p.hubspot_owner_id)] ? { Salesperson: users[String(p.hubspot_owner_id)] } : {}),
      ...(users[String(p.project_manager)] ? { ProjectManager: users[String(p.project_manager)] } : {}),
      DueDate: p.due_date ? asDate(p.due_date).toFormat('yyyy-MM-dd') : null,
      OrderNo: p.orderno ?? '',
      ...(isQuote && p.validity ? { ValidityDays: Number(p.validity) } : {}),
      Tags: (p.project_tags ?? '').split(';').filter(Boolean).map(Number),
    };
    // Only set when the record is CREATED: the type, and for quotes the sales person. The Simpro -> HubSpot quote mapping puts the
    // PROJECT MANAGER in hubspot_owner_id (carried-over quirk), so syncing the owner back would overwrite a quote's real sales person.
    out.createExtra = { Type: (isQuote ? p.quote_type : p.job_type) ?? '', ...(isQuote && users[String(p.hubspot_owner_id)] ? { Salesperson: users[String(p.hubspot_owner_id)] } : {}) };
    if (isQuote) out.customFields = [
      { id: cfg.customFields.tenderNumber, value: p.tender_number ?? '' },
      { id: cfg.customFields.tenderStatus, value: p.tender_status ?? '' },
      { id: cfg.customFields.vertical, value: p.vertical ?? '' },
    ];
    out.lineItems = (assoc.line_items[rec.hsId] ?? []).map(t => ({ id: t.id, ...(lineItem[t.id] ?? {}) }));
  }
  plan.push(out);
}
return [{ json: { records: plan, skipped } }];

// Node: Build Simpro Reads   (all five HubSpot -> Simpro sync workflows)
// Compare before write: for every record that already has a Simpro ID, read what Simpro holds today, so we only
// write when something really differs. This is what stops the HubSpot <-> Simpro ping-pong. Reads are throttled.
const { records } = $('Resolve Plan').first().json;
const reads = records.filter(r => r.simproId).map(r => ({ json: { url: r.updateUrl, meta: { hsId: r.hsId } } }));
if (reads.length === 0) return [{ json: { skip: true } }];
return reads;

// Node: Build Record Writes   (all five HubSpot -> Simpro sync workflows)
// New record (no Simpro ID) -> create it. Existing record -> update ONLY the fields that differ from what Simpro
// holds today (nothing to update = no call). A record Simpro no longer has (404) or could not be read is left alone
// and reported by Finish Run; it is never re-created.
const cfg = $('Build Sync Window').first().json;
const plan = $('Resolve Plan').first().json.records;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } }; // [] when that stage did not run
const live = (name) => safeAll(name).filter(i => !(i.json && i.json.skip));
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
// What Simpro holds today for each record we are updating (from Read from Simpro)
const current = {};
{ const reqs = live('Build Simpro Reads');
  live('Read from Simpro').forEach((item, k) => { const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {}; if (r.statusCode === 200) current[m.hsId] = r.body; }); }
// Simpro IDs created in this run (from Write Records to Simpro)
const created = {};
{ const reqs = live('Build Record Writes');
  live('Write Records to Simpro').forEach((item, k) => { const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {};
    if (m.kind === 'create' && (r.statusCode === 200 || r.statusCode === 201) && r.body && r.body.ID !== undefined) created[m.hsId] = String(r.body.ID); }); }
const finalId = (rec) => rec.simproId ?? created[rec.hsId] ?? null;
const recordUrl = (rec) => rec.createUrl.replace(/\/$/, '') + '/' + finalId(rec);


const norm = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const same = (want, have) => {
  if (Array.isArray(want)) { // lists of IDs (tags)
    const h = (Array.isArray(have) ? have : []).map(t => Number(t && t.ID !== undefined ? t.ID : t));
    return JSON.stringify([...want].map(Number).sort()) === JSON.stringify(h.sort());
  }
  if (want !== null && typeof want === 'object') return Object.entries(want).every(([k, v]) => same(v, have ? have[k] : undefined));
  if (have !== null && typeof have === 'object' && have.ID !== undefined) return norm(want) === norm(have.ID); // { ID } references
  return norm(want) === norm(have);
};

const writes = [];
for (const rec of plan) {
  if (rec.simproId) {
    const cur = current[rec.hsId];
    if (!cur) continue; // gone in Simpro or unreadable: reported by Finish Run
    const patch = {};
    for (const [k, v] of Object.entries(rec.body)) if (!same(v, cur[k])) patch[k] = v;
    if (Object.keys(patch).length) writes.push({ json: { method: 'PATCH', url: rec.updateUrl, body: patch, meta: { hsId: rec.hsId, kind: 'update', fields: Object.keys(patch) } } });
  } else {
    writes.push({ json: { method: 'POST', url: rec.createUrl, body: { ...rec.body, ...rec.createExtra }, meta: { hsId: rec.hsId, kind: 'create' } } });
  }
}
if (writes.length === 0) return [{ json: { skip: true } }];
return writes;

// Node: Build ID Write-Back   (all five HubSpot -> Simpro sync workflows)
// Right after a record is created in Simpro, save its new Simpro ID on the HubSpot record (batches of 100).
// Doing this straight away is what prevents a second run from creating the same record in Simpro twice.
const cfg = $('Build Sync Window').first().json;
const plan = $('Resolve Plan').first().json.records;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } }; // [] when that stage did not run
const live = (name) => safeAll(name).filter(i => !(i.json && i.json.skip));
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
// What Simpro holds today for each record we are updating (from Read from Simpro)
const current = {};
{ const reqs = live('Build Simpro Reads');
  live('Read from Simpro').forEach((item, k) => { const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {}; if (r.statusCode === 200) current[m.hsId] = r.body; }); }
// Simpro IDs created in this run (from Write Records to Simpro)
const created = {};
{ const reqs = live('Build Record Writes');
  live('Write Records to Simpro').forEach((item, k) => { const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {};
    if (m.kind === 'create' && (r.statusCode === 200 || r.statusCode === 201) && r.body && r.body.ID !== undefined) created[m.hsId] = String(r.body.ID); }); }
const finalId = (rec) => rec.simproId ?? created[rec.hsId] ?? null;
const recordUrl = (rec) => rec.createUrl.replace(/\/$/, '') + '/' + finalId(rec);


const updates = Object.entries(created).map(([hsId, simproId]) => ({ id: hsId, properties: { [cfg.idProperty]: simproId } }));
if (updates.length === 0) return [{ json: { skip: true } }];
return chunk(updates, 100).map((part, n) => ({
  json: { url: cfg.hubspotApiBase + '/' + cfg.objectPath + '/batch/update', body: { inputs: part }, meta: { batch: n + 1, count: part.length } },
}));

// Node: Build Section Reads   (quotes and jobs)
// For every deal that has line items: read the sections of its Simpro quote/job (cost centers live inside sections).
const cfg = $('Build Sync Window').first().json;
const plan = $('Resolve Plan').first().json.records;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } }; // [] when that stage did not run
const live = (name) => safeAll(name).filter(i => !(i.json && i.json.skip));
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
